VAR
    MotorLatch : BOOL := FALSE;
    EStopTimer : TON;
END_VAR

EStopTimer(IN := NOT(EStop), PT := T#0s);

IF EStopTimer.Q THEN
    MotorLatch := FALSE;
    Motor := FALSE;
ELSIF Start AND NOT(MotorLatch) THEN
    MotorLatch := TRUE;
    Motor := TRUE;
ELSIF Stop OR EStop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
END_IF;

Motor := MotorLatch AND NOT(EStop);
