PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    motor_latched : BOOL := FALSE;
    estop_timer : TON;
END_VAR

// Check for EStop activation
IF NOT EStop THEN
    // EStop is active, de-energize the motor and clear any previous latching
    Motor := FALSE;
    motor_latched := FALSE;
    estop_timer(IN := TRUE, PT := T#0s);
ELSE
    // EStop is inactive, check Start and Stop conditions
    IF Start AND NOT Stop THEN
        // Start is pressed and Stop is not, latch the motor on
        motor_latched := TRUE;
    ELSIF Stop THEN
        // Stop is pressed, unlatch the motor off
        motor_latched := FALSE;
    END_IF;

    // Set the motor output based on the latched state
    Motor := motor_latched;
END_IF;

END_PROGRAM

