PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LastPumpIn : BOOL := FALSE;
    LastValveOut : BOOL := FALSE;
    LowLimit : INT := 10;
    HighLimit : INT := 90;
END_VAR

// Check if we need to change the state of PumpIn
IF Level <= LowLimit AND NOT LastPumpIn THEN
    PumpIn := TRUE;
ELSIF Level >= HighLimit OR (LastPumpIn AND NOT Level > HighLimit) THEN
    PumpIn := FALSE;
END_IF;

// Check if we need to change the state of ValveOut
IF Level >= HighLimit AND NOT LastValveOut THEN
    ValveOut := TRUE;
ELSIF Level < HighLimit OR (LastValveOut AND NOT Level >= HighLimit) THEN
    ValveOut := FALSE;
END_IF;

// Update the last states
LastPumpIn := PumpIn;
LastValveOut := ValveOut;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    prev_pump_state : BOOL := FALSE;
    prev_valve_state : BOOL := FALSE;
END_VAR

IF Level <= 10 THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= 90 THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := prev_pump_state;
    ValveOut := prev_valve_state;
END_IF;

prev_pump_state := PumpIn;
prev_valve_state := ValveOut;
END_PROGRAM

