PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    last_pump_state : BOOL := FALSE;
    last_valve_state : BOOL := FALSE;
    last_level : INT := 0;
END_VAR

// Check if the level has changed
IF Level <> last_level THEN
    // Update the previous level
    last_level := Level;

    // Turn off the pump if it's on and the level is above the high limit
    IF PumpIn AND (Level >= 90) THEN
        PumpIn := FALSE;
    ELSIF NOT PumpIn AND (Level <= 10) THEN
        PumpIn := TRUE;
    END_IF;

    // Turn on the outlet valve if the level is at or above the high limit
    IF Level >= 90 THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;

    // Ensure the pump does not run while the level is at or above the high limit
    IF PumpIn AND (Level >= 90) THEN
        PumpIn := FALSE;
    END_IF;
END_IF;

// Store the current state for next cycle
last_pump_state := PumpIn;
last_valve_state := ValveOut;
END_PROGRAM

