PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Latch : BOOL := FALSE;
    DoorB_Latch : BOOL := FALSE;
    PriorityTimer : TON;
END_VAR

// Check for priority of Door A
IF OpenA_Cmd AND NOT OpenB_Cmd THEN
    PriorityTimer(IN := TRUE, PT := T#0s);
ELSIF OpenB_Cmd AND NOT OpenA_Cmd THEN
    PriorityTimer(IN := FALSE, PT := T#0s);
ELSE
    PriorityTimer(IN := FALSE, PT := T#0s);
END_IF;

// Apply priority and open/close latches
IF PriorityTimer.Q THEN
    DoorA_Latch := TRUE;
    DoorB_Latch := FALSE;
ELSIF NOT OpenA_Cmd AND NOT OpenB_Cmd THEN
    DoorA_Latch := FALSE;
    DoorB_Latch := FALSE;
END_IF;

// Assign output based on latches
DoorA := DoorA_Latch;
DoorB := DoorB_Latch;

END_PROGRAM

