PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Latch : BOOL := FALSE;
    DoorB_Latch : BOOL := FALSE;
    PriorityTimer : TON;
END_VAR

// Check if both doors are requested to open simultaneously
IF OpenA_Cmd AND OpenB_Cmd THEN
    // Door A gets priority
    DoorA_Latch := TRUE;
    DoorB_Latch := FALSE;
    PriorityTimer(IN := TRUE, PT := T#0s);
ELSE
    // Normal operation
    IF OpenA_Cmd AND NOT DoorB_Latch THEN
        DoorA_Latch := TRUE;
        DoorB_Latch := FALSE;
    ELSE
        DoorA_Latch := FALSE;
    END_IF;

    IF OpenB_Cmd AND NOT DoorA_Latch THEN
        DoorB_Latch := TRUE;
        DoorA_Latch := FALSE;
    ELSE
        DoorB_Latch := FALSE;
    END_IF;
END_IF;

// Reset latches if the other door opens
IF DoorA_Latch AND OpenB_Cmd THEN
    DoorA_Latch := FALSE;
END_IF;

IF DoorB_Latch AND OpenA_Cmd THEN
    DoorB_Latch := FALSE;
END_IF;

// Assign outputs based on latches
DoorA := DoorA_Latch;
DoorB := DoorB_Latch;
END_PROGRAM

