PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    ConveyorRunning : BOOL := FALSE;
    StartTimer : TON;
END_VAR

// Start the conveyor if StartPB is pressed, the guard is closed, and there's no fault
IF StartPB AND GuardClosed AND NOT Fault THEN
    StartTimer(IN := TRUE, PT := T#0s);
ELSIF StopPB OR NOT GuardClosed OR Fault THEN
    StartTimer(IN := FALSE);
    ConveyorRunning := FALSE;
END_IF;

// Update the conveyor state based on the timer and safety conditions
IF StartTimer.Q THEN
    ConveyorRunning := TRUE;
END_IF;

// Apply the safety condition to stop the conveyor
Conveyor := ConveyorRunning AND GuardClosed AND NOT Fault;
END_PROGRAM

