PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    NS_green_timer, NS_yellow_timer, NS_allred_timer : TON;
    EW_green_timer, EW_yellow_timer, EW_allred_timer : TON;
END_VAR

// Initialize timers
NS_green_timer(IN := FALSE, PT := T#2s);
NS_yellow_timer(IN := FALSE, PT := T#1s);
NS_allred_timer(IN := FALSE, PT := T#1s);
EW_green_timer(IN := FALSE, PT := T#2s);
EW_yellow_timer(IN := FALSE, PT := T#1s);
EW_allred_timer(IN := FALSE, PT := T#1s);

CASE State OF
    0: // NS green, EW red
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        NS_green_timer(IN := TRUE);
        IF NS_green_timer.Q THEN
            State := 1;
        END_IF;

    1: // NS yellow, EW red
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        NS_yellow_timer(IN := TRUE);
        IF NS_yellow_timer.Q THEN
            State := 2;
        END_IF;

    2: // All red
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        NS_allred_timer(IN := TRUE);
        IF NS_allred_timer.Q THEN
            State := 3;
        END_IF;

    3: // EW green, NS red
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
        EW_green_timer(IN := TRUE);
        IF EW_green_timer.Q THEN
            State := 4;
        END_IF;

    4: // EW yellow, NS red
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
        EW_yellow_timer(IN := TRUE);
        IF EW_yellow_timer.Q THEN
            State := 5;
        END_IF;

    5: // All red
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        EW_allred_timer(IN := TRUE);
        IF EW_allred_timer.Q THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

