PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR

VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR

VAR
    State : INT := 0;
    UpTimer : TON;
    DownTimer : TON;
END_VAR

CASE State OF
    0: // At-bottom
        MotorUp := FALSE;
        MotorDown := FALSE;
        IF CallUp AND DoorClosed THEN
            State := 1;
            UpTimer(IN := TRUE, PT := T#0s);
        END_IF;

    1: // Moving-up
        MotorUp := TRUE;
        MotorDown := FALSE;
        IF Not DoorClosed OR AtTop THEN
            MotorUp := FALSE;
        ELSIF UpTimer.Q THEN
            IF CallDown AND Not AtBottom THEN
                State := 3;
                DownTimer(IN := TRUE, PT := T#0s);
            ELSE
                State := 2;
            END_IF;
        END_IF;

    2: // At-top
        MotorUp := FALSE;
        MotorDown := FALSE;
        IF CallDown AND DoorClosed THEN
            State := 3;
            DownTimer(IN := TRUE, PT := T#0s);
        END_IF;

    3: // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF Not DoorClosed OR AtBottom THEN
            MotorDown := FALSE;
        ELSIF DownTimer.Q THEN
            IF CallUp AND Not AtTop THEN
                State := 1;
                UpTimer(IN := TRUE, PT := T#0s);
            ELSE
                State := 0;
            END_IF;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    T_Emergency : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

T_Emergency(IN := NOT EStop, PT := T#0s);

CASE State OF
    0: // Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

    1: // Fill
        IF T_Emergency.Q OR Level >= LVL_HIGH OR Level < LIQ_MIN THEN
            State := 0;
        ELSIF EStop THEN
            State := 0;
        ELSE
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    2: // Heat
        IF T_Emergency.Q OR Temp >= TEMP_SET OR Level < LIQ_MIN THEN
            State := 3;
        ELSIF EStop THEN
            State := 0;
        ELSE
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        END_IF;

    3: // React
        IF T_Emergency.Q OR Level < LIQ_MIN THEN
            State := 0;
        ELSIF EStop THEN
            State := 0;
        ELSIF T_Emergency.Q OR T_Emergency(PT := PT_REACT).Q THEN
            State := 4;
        ELSE
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        END_IF;

    4: // Drain
        IF T_Emergency.Q OR Level <= LVL_LOW OR Level < LIQ_MIN THEN
            State := 0;
        ELSIF EStop THEN
            State := 0;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    T_Fill : TON;
    T_React : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        T_Fill(IN := TRUE, PT := T#1s);
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

        IF Level >= LVL_HIGH OR NOT StartBatch THEN
            State := 2;
        END_IF;

    2: // Heat
        T_Fill(IN := FALSE);
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: // React
        T_React(IN := TRUE, PT := PT_REACT);
        T_Fill(IN := FALSE);
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF NOT T_React.Q THEN
            State := 4;
        END_IF;

    4: // Drain
        T_Fill(IN := FALSE);
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    HeatTimer : TON;
    ReactTimer : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
    FillTimer(IN := FALSE);
    HeatTimer(IN := FALSE);
    ReactTimer(IN := FALSE);
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0: // Idle
            IF EStop THEN
                State := 0;
            ELSEIF StartBatch THEN
                State := 1;
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
                FillTimer(IN := TRUE, PT := T#5s);
            END_IF;

        1: // Fill
            IF EStop OR FillTimer.Q THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSIF Level >= LVL_HIGH THEN
                State := 2;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
                HeatTimer(IN := TRUE, PT := T#10s);
            END_IF;

        2: // Heat
            IF EStop OR Not Level >= LIQ_MIN THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSIF Temp >= TEMP_SET THEN
                State := 3;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
                ReactTimer(IN := TRUE, PT := PT_REACT);
            END_IF;

        3: // React
            IF EStop OR Not Level >= LIQ_MIN THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSIF ReactTimer.Q THEN
                State := 4;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;

        4: // Drain
            IF EStop OR Level <= LVL_LOW THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSIF Level <= LVL_LOW THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    HeatTimer : TON;
    PT_REACT : TIME := T#3s;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
END_VAR

CASE State OF
    0: // Idle
        IF StartBatch AND NOT EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH OR EStop THEN
            FillValve := FALSE;
            State := 2;
        END_IF;

    2: // Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN OR EStop THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 3;
        END_IF;

    3: // React
        Heater := TRUE;
        Agitator := TRUE;
        IF HeatTimer.Q OR EStop THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 4;
        ELSE
            HeatTimer(IN := TRUE, PT := PT_REACT);
        END_IF;

    4: // Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR EStop THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

// Safety checks
IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

// Prevent simultaneous fill and drain
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

