PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LevelMin : INT := 10;
    LvlHigh : INT := 80;
    LvlLow : INT := 5;
    TempSet : INT := 100;
    PtReact : TIME := T#3s;
    TmrReact : TON;
END_VAR

TmrReact(IN := NOT EStop AND (State = 2 OR State = 3), PT := PtReact);

CASE State OF
    0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF Level >= LvlHigh THEN
            State := 2;
        ELSIF NOT EStop THEN
            State := 0;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF Temp >= TempSet AND TmrReact.Q THEN
            State := 3;
        ELSIF NOT EStop THEN
            State := 0;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF NOT TmrReact.Q THEN
            TmrReact(IN := TRUE, PT := PtReact);
        END_IF;
        IF NOT EStop THEN
            State := 0;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LvlLow THEN
            State := 0;
        ELSIF NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

// Prevent fill and drain valves from being open at the same time
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

// Prevent dry firing
IF Level < LevelMin AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

