    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF EStop OR Temp >= TEMP_SET OR NOT StartBatch THEN
            State := 0;
        ELSIF NOT EStop AND Level < LIQ_MIN THEN
            State := 0;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF EStop OR NOT StartBatch THEN
            State := 0;
        ELSIF T_ReactTimer.Q THEN
            State := 4;
            T_ReactTimer(IN := FALSE);
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
