        DrainValve := TRUE;
        IF EStop OR Level <= LVL_LOW OR NOT StartBatch THEN
            State := 0;
        ELSIF T_DrainTimer.Q THEN
            State := 0;
        END_IF;
END_CASE;

// TON Timers
T_FillTimer(IN := FALSE, PT := T#5s);
T_ReactTimer(IN := FALSE, PT := PT_REACT);
