        DeltaK := FALSE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF StarTimer.Q THEN
            StarTimer(IN := FALSE);
            State := 2;
        ELSE
            StarTimer(IN := TRUE, PT := T#3s);
        END_IF;

    2: // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

