PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND Level < 90 THEN
            State := 1;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF Level >= 90 OR EStop THEN
            State := 2;
        ELSIF NOT EStop THEN
            FillTimer(IN := TRUE, PT := T#5s);
            IF NOT FillTimer.Q THEN
                Pump := FALSE;
            END_IF;
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= 10 OR EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

// Prevent both pump and valve from being on
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

// Ensure pump never runs at/above HIGH
IF Level >= 90 AND Pump THEN
    Pump := FALSE;
END_IF;

// Ensure valve never opens at/below LOW
IF Level <= 10 AND Valve THEN
    Valve := FALSE;
END_IF;
END_PROGRAM

