    Fuel : BOOL;
    Ignition : BOOL;
END_VAR

VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

PurgeTimer(IN := NOT EStop AND (State = 1), PT := T#3s);
IgnitionTimer(IN := NOT EStop AND (State = 2), PT := T#2s);

CASE State OF
    0: // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;

    1: // Pre-purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;

    2: // Ignition trial
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

