IF NOT Demand AND PrevDemand THEN
    DemandTimer(IN := FALSE); // Stop demand timer
    IF DemandTimer.Q THEN
        // Alternate lead on demand end
        IF Lead = 0 THEN
            Lead := 1;
        ELSE
            Lead := 0;
        END_IF;
    END_IF;
END_IF;

// Assign pumps based on lead and demand
CASE Lead OF
    0: Pump1 := Demand; Pump2 := FALSE;
    1: Pump1 := FALSE; Pump2 := Demand;
    ELSE: Pump1 := FALSE; Pump2 := FALSE; // Should not happen
END_CASE;

