END_IF;

// Increment Count on rising edge of Trigger
IF PrevTrigger AND NOT Trigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
END_IF;

// Set Done when Count reaches 3
Done := (Count = 3);

// Clear Count and Done on Reset
IF Reset THEN
    Count := 0;
    Done := FALSE;
END_IF;

END_PROGRAM
